// src/NewEntry.js
import React, { useState } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";

export default function NewEntry() {
  const [form, setForm] = useState({
    title: "",
    category: "Study",
    date: "",
    mood: "😊 Happy",
    tags: "",
    security: "Private",
    notes: "",
  });

  const navigate = useNavigate();

  const handleChange = (e) => {
    const { name, value } = e.target;
    setForm((s) => ({ ...s, [name]: value }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    // For demo: local confirm
    // To save: POST to backend with token
    const token = localStorage.getItem("token");
    try {
      if (token) {
        await axios.post("http://localhost:5000/api/entries", form, {
          headers: { Authorization: `Bearer ${token}` },
        });
      }
      alert("Saved!");
      navigate("/dashboard");
    } catch (err) {
      console.error(err);
      alert("Save failed. Check server.");
    }
  };

  return (
    <div className="max-w-3xl mx-auto bg-white shadow-xl rounded-2xl p-8">
      <h2 className="text-2xl font-bold mb-6">New Entry</h2>
      <form onSubmit={handleSubmit} className="space-y-4">
        {/* ...fields like title, category, date, mood, tags, notes... */}
        <input name="title" value={form.title} onChange={handleChange} placeholder="Title" className="w-full p-3 border rounded-lg" required />
        {/* other inputs similar */}
        <div className="flex gap-3">
          <button type="submit" className="px-4 py-2 bg-indigo-600 text-white rounded-lg">Save</button>
          <button type="button" onClick={() => navigate("/dashboard")} className="px-4 py-2 border rounded-lg">Cancel</button>
        </div>
      </form>
    </div>
  );
}
